// Append the binary representation of sequence and type to dst
void AppendInternalKey(std::string* dst, const InternalKey& internal_key);

// Returns the length of the encoding of the sequence number and type.
extern const int kNumInternalBytes = 8;  // 7 for sequence, 1 for type

// Decode the sequence number and type from the last 8 bytes of internal_key.
// On success, stores the sequence number in *sequence and returns the type.
// The type is stored as a uint8_t, but can be read as a ValueType.
extern ValueType DecodeFixed64(const char* dst);

